-- 交易台数据库导出（截至 2026-05-15 收盘）。导入方法：sqlite3 desk.db < 交易台数据库.sql
-- 表：instruments（股票清单）、sectors（行业）、restricted_list_history（限制名单历史）、pilot_fills、pilot_positions、pilot_status、pilot_weights（回测引擎试运行的成交、持仓和每日状态表）。
BEGIN TRANSACTION;
CREATE TABLE "sectors" ("sector_code" TEXT PRIMARY KEY, "sector_name" TEXT NOT NULL);
CREATE TABLE "instruments" ("ticker" TEXT PRIMARY KEY, "sector_code" TEXT NOT NULL REFERENCES sectors, "board_lot" INTEGER NOT NULL, "half_spread_bp" INTEGER NOT NULL, "shares_outstanding" INTEGER NOT NULL);
CREATE TABLE "restricted_list_history" ("ticker" TEXT NOT NULL, "notice_date" TEXT NOT NULL, "effective_date" TEXT NOT NULL, "removed_date" TEXT, "reason" TEXT);
CREATE TABLE "pilot_fills" ("session_date" TEXT NOT NULL, "ticker" TEXT NOT NULL, "side" TEXT NOT NULL, "qty" INTEGER NOT NULL, "at" TEXT NOT NULL, "price" REAL NOT NULL, "fee" REAL NOT NULL, "sales_tax" REAL NOT NULL);
CREATE TABLE "pilot_positions" ("date" TEXT NOT NULL, "ticker" TEXT NOT NULL, "shares" INTEGER NOT NULL, "close" REAL NOT NULL, "market_value" REAL NOT NULL);
CREATE TABLE "pilot_status" ("date" TEXT PRIMARY KEY, "cash" REAL NOT NULL, "unsettled" REAL NOT NULL, "equity" REAL NOT NULL, "buying_power" REAL NOT NULL, "drawdown_pct" REAL NOT NULL);
CREATE TABLE "pilot_weights" ("date" TEXT NOT NULL, "kind" TEXT NOT NULL, "code" TEXT NOT NULL, "weight_pct" REAL NOT NULL);
COMMIT;
